// Convert input points to CGAL points
CGALPoint cgalP1(p1.x(), p1.y(), p1.z());
CGALPoint cgalP2(p2.x(), p2.y(), p2.z());

// Create a CGAL ray from the segment
CGALRay ray(cgalP1, cgalP2);

// Query the AABB tree for intersections with the ray
std::list<Tree::Primitive_id> intersections;
tree.tree.all_intersections(ray, std::back_inserter(intersections));

// Count unique primitives (triangles) intersected
std::set<typename std::list<Tree::Primitive_id>::value_type> uniquePrimitives;
for (const auto& intersection : intersections) {
    if (const CGALTriangle* triangle = boost::get<CGALTriangle>(&intersection->first)) {
        uniquePrimitives.insert(intersection->second);
    }
}

return static_cast<int>(uniquePrimitives.size());

